using System.Globalization;

namespace TrayRadar.Services;

/// <summary>
/// Offline US ZIP code → coordinate lookup backed by the bundled Census ZCTA centroids
/// (Assets/Data/zcta.csv, generated by tools/Build-ZipData.ps1).
/// </summary>
internal static class ZipLookupService
{
    private static Dictionary<string, (double Lat, double Lon)>? s_table;
    private static readonly SemaphoreSlim s_loadLock = new(1, 1);

    public static bool IsWellFormed(string? zip) =>
        zip is { Length: 5 } && zip.All(char.IsAsciiDigit);

    public static async Task<(double Lat, double Lon)?> TryLookupAsync(string zip)
    {
        if (!IsWellFormed(zip))
        {
            return null;
        }

        Dictionary<string, (double, double)> table = await EnsureLoadedAsync();
        return table.TryGetValue(zip, out (double, double) point) ? point : null;
    }

    /// <summary>
    /// Drops the in-memory table (call when no window can look up a ZIP). The next lookup reloads
    /// it from disk. Does nothing while a load is running.
    /// </summary>
    public static void Unload()
    {
        if (!s_loadLock.Wait(0))
        {
            return;
        }

        s_table = null;
        s_loadLock.Release();
    }

    private static async Task<Dictionary<string, (double, double)>> EnsureLoadedAsync()
    {
        if (s_table is not null)
        {
            return s_table;
        }

        await s_loadLock.WaitAsync();
        try
        {
            s_table ??= await Task.Run(Load);
            return s_table;
        }
        finally
        {
            s_loadLock.Release();
        }
    }

    private static Dictionary<string, (double, double)> Load()
    {
        string path = Path.Combine(AppContext.BaseDirectory, "Assets", "Data", "zcta.csv");
        Dictionary<string, (double, double)> table = new(34_000, StringComparer.Ordinal);

        foreach (string line in File.ReadLines(path).Skip(1))
        {
            string[] parts = line.Split(',');
            if (parts.Length == 3
                && double.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out double lat)
                && double.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out double lon))
            {
                table[parts[0]] = (lat, lon);
            }
        }

        return table;
    }
}
